const SECRET = "";

/* Задания: JSON, перемешанный XOR с байтами соли, в base64. Раскодируются при загрузке страницы. */
QUIZ.questions = (() => {
  const pad = new TextEncoder().encode(QUIZ.salt);
  const bytes = Uint8Array.from(atob(""), c => c.charCodeAt(0)).map((b, i) => b ^ pad[i % pad.length]);
  return JSON.parse(new TextDecoder().decode(bytes));
})();

let SECRET_CACHE = null;
async function secretData() {
  if (SECRET_CACHE) return SECRET_CACHE;
  const pad = new Uint8Array(await crypto.subtle.digest('SHA-256', new TextEncoder().encode(QUIZ.salt)));
  const bytes = Uint8Array.from(atob(SECRET), c => c.charCodeAt(0)).map((b, i) => b ^ pad[i % pad.length]);
  SECRET_CACHE = JSON.parse(new TextDecoder().decode(bytes));
  return SECRET_CACHE;
}

async function shortHash(text) {
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text));
  return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('').slice(0, 16);
}

/* ---------- тренажёр панели Source Control ----------
   Ответ — журнал действий: a3 — плюс у файла 3, A — плюс у заголовка Changes (все файлы),
   u3 — минус у файла 3 в Staged Changes, d3 — Discard Changes у файла 3, c1 — Commit с сообщением 1.
   Состояние файла: w — в Changes, s — в Staged Changes, x — выброшен, k — записан в коммит. */
function simRun(q, log) {
  const zone = q.sfiles.map(() => 'w');
  const commits = [];
  for (const t of log || []) {
    const op = t[0], i = Number(t.slice(1));
    if (op === 'a' && zone[i] === 'w') zone[i] = 's';
    else if (op === 'A') zone.forEach((z, j) => { if (z === 'w') zone[j] = 's'; });
    else if (op === 'u' && zone[i] === 's') zone[i] = 'w';
    else if (op === 'd' && zone[i] === 'w') zone[i] = 'x';
    else if (op === 'c') {
      const f = zone.map((z, j) => z === 's' ? j : -1).filter(j => j >= 0);
      if (f.length) { commits.push({ m: i, f }); f.forEach(j => { zone[j] = 'k'; }); }
    }
  }
  return { zone, commits };
}

/* Итог тренажёра одной строкой: коммиты по порядку, затем Staged, Changes и выброшенные файлы. */
function simSig(q, log) {
  const { zone, commits } = simRun(q, log);
  const pick = z => zone.map((v, j) => v === z ? j : -1).filter(j => j >= 0).join('.');
  return 'C=' + commits.map(c => c.m + ':' + c.f.join('.')).join(';') + '|S=' + pick('s') + '|W=' + pick('w') + '|X=' + pick('x');
}

function simParse(sig) {
  const part = {};
  sig.split('|').forEach(p => { const [k, v] = p.split('='); part[k] = v; });
  const nums = v => v ? v.split('.').map(Number) : [];
  return {
    commits: part.C ? part.C.split(';').map(c => { const [m, f] = c.split(':'); return { m: Number(m), f: nums(f) }; }) : [],
    staged: nums(part.S), changes: nums(part.W), discard: nums(part.X)
  };
}

/* ---------- .gitignore ----------
   Строки применяются в порядке списка q.rules. Последняя подошедшая строка решает;
   ! делает исключение; косая черта в конце — только папка; косая черта в начале или середине
   привязывает шаблон к корню, без неё шаблон сравнивается с именем в любой папке.
   Файл внутри скрытой папки скрыт, исключение его не возвращает. */
function ignRules(q, sel) {
  return [...sel].sort((a, b) => a - b).map(i => {
    let p = q.rules[i], neg = false, dir = false;
    if (p[0] === '!') { neg = true; p = p.slice(1); }
    if (p.endsWith('/')) { dir = true; p = p.slice(0, -1); }
    const anch = p.includes('/');
    if (p[0] === '/') p = p.slice(1);
    const re = new RegExp('^' + p.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '[^/]*').replace(/\?/g, '[^/]') + '$');
    return { neg, dir, anch, re };
  });
}

function ignMatch(rules, path, isDir) {
  const base = path.split('/').pop();
  let res = false;
  for (const r of rules) {
    if (r.dir && !isDir) continue;
    if (r.re.test(r.anch ? path : base)) res = !r.neg;
  }
  return res;
}

/* Номера скрытых файлов из q.paths при выбранных строках. */
function ignored(q, sel) {
  const rules = ignRules(q, sel);
  return q.paths.map((p, i) => {
    const parts = p.split('/');
    for (let k = 1; k < parts.length; k++) if (ignMatch(rules, parts.slice(0, k).join('/'), true)) return i;
    return ignMatch(rules, p, false) ? i : -1;
  }).filter(i => i >= 0);
}

/* Приводит ответ к форме ключа. Пустой или неполный ответ даёт null. */
function normalized(q, a) {
  if (a == null) return null;
  switch (q.type) {
    case 'single': case 'multi': case 'line': case 'odd': case 'node': case 'grid':
      return a.length ? [...a].sort((x, y) => x - y) : null;
    case 'order': case 'path': case 'build': case 'fix':
      return a.length ? a : null;
    case 'slots': case 'sort': case 'table':
      return a.every(x => x !== null && x !== undefined) ? a : null;
    case 'number': {
      const s = String(a).replace(/\s/g, '').replace(',', '.');
      return s !== '' && isFinite(Number(s)) ? [Number(s)] : null;
    }
    case 'sim':
      return a.length ? [simSig(q, a)] : null;
    case 'ignore':
      return a.length ? ignored(q, a) : null;
  }
  return null;
}

/* Баллы за задание от 0 до 1. Полностью верный ответ — 1. Задание из нескольких частей
   при неполном ответе получает долю, округлённую вниз до десятых:
   карточки (slots, sort, order) — доля верно поставленных;
   отметки (multi, odd, grid, ignore, line и node с many) — (верные − ошибочные) / нужные, не меньше нуля;
   sort со start — считаются только файлы, которые нужно было перенести, ошибочно перенесённые снимают долю;
   sim — доля верных мест файлов (в каком коммите, в Changes, выброшен) и верных сообщений коммитов.
   table — доля верных клеток; build — (блоки общей подпоследовательности с ключом − лишние блоки) / длина ключа;
   fix — (верно заменённые строки − ошибочно тронутые) / строки, которые нужно заменить.
   single, number, line и node без many, build с accept — 0 или 1. */
function lcs(a, b) {
  const d = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
  for (let i = 1; i <= a.length; i++)
    for (let j = 1; j <= b.length; j++)
      d[i][j] = a[i - 1] === b[j - 1] ? d[i - 1][j - 1] + 1 : Math.max(d[i - 1][j], d[i][j - 1]);
  return d[a.length][b.length];
}

function simPlace(st, i) {
  const c = st.commits.findIndex(x => x.f.includes(i));
  if (c >= 0) return 'c' + c;
  return st.staged.includes(i) ? 's' : st.changes.includes(i) ? 'w' : 'x';
}

function partialOf(q, norm, key) {
  switch (q.type) {
    case 'multi': case 'odd': case 'grid': case 'ignore': case 'line': case 'node': {
      if ((q.type === 'line' || q.type === 'node') && !q.many) return 0;
      const hits = norm.filter(x => key.includes(x)).length;
      return (hits - (norm.length - hits)) / key.length;
    }
    case 'slots': case 'order': case 'table':
      return norm.filter((x, i) => x === key[i]).length / key.length;
    case 'build': {
      if (q.accept) return 0;
      const hits = lcs(norm, key);
      return (hits - (norm.length - hits)) / key.length;
    }
    case 'fix': {
      const need = key.map((v, i) => v !== 0 ? i : -1).filter(i => i >= 0);
      const hits = need.filter(i => norm[i] === key[i]).length;
      const bad = norm.filter((v, i) => key[i] === 0 && v !== 0).length;
      return (hits - bad) / need.length;
    }
    case 'sort': {
      if (!q.start) return norm.filter((x, i) => x === key[i]).length / key.length;
      const need = key.map((b, i) => b !== q.start[i] ? i : -1).filter(i => i >= 0);
      const hits = need.filter(i => norm[i] === key[i]).length;
      const bad = norm.filter((b, i) => key[i] === q.start[i] && b !== key[i]).length;
      return (hits - bad) / need.length;
    }
    case 'sim': {
      const mine = simParse(norm[0]), want = simParse(key[0]);
      let ok = q.sfiles.filter((_, i) => simPlace(mine, i) === simPlace(want, i)).length;
      ok += want.commits.filter((c, j) => mine.commits[j] && mine.commits[j].m === c.m).length;
      return ok / (q.sfiles.length + want.commits.length);
    }
  }
  return 0;
}

async function pointsFor(q, a) {
  const norm = normalized(q, a);
  if (!norm) return 0;
  const key = (await secretData())[q.id].key;
  if (q.accept) return key.some(k => JSON.stringify(norm) === JSON.stringify(k)) ? 1 : 0;
  if (JSON.stringify(norm) === JSON.stringify(key)) return 1;
  const f = Math.floor(Math.max(0, partialOf(q, norm, key)) * 10 + 1e-9) / 10;
  return Math.min(f, 0.9);
}

async function isCorrect(q, a) {
  return (await pointsFor(q, a)) === 1;
}

/* Баллы с запятой: 17,5 */
function fmtPts(x) {
  return String(Math.round(x * 10) / 10).replace('.', ',');
}

/* Ответ в коде результата: строка на вопрос. Номера — одним символом (узлы, строки кода, клетки, строки .gitignore,
   блоки сборщика, значения таблицы — в base36), пусто — x. Журнал тренажёра — токены подряд: a0a1c0A c1 без пробелов. */
const B36 = ['node', 'line', 'grid', 'ignore', 'build'];

function encodeAnswer(q, a) {
  if (a == null) return '';
  if (q.type === 'number') return String(a).replace(/[^0-9.,\-]/g, '').slice(0, 12);
  if (q.type === 'slots' || q.type === 'sort' || q.type === 'table') return a.map(x => (x === null || x === undefined) ? 'x' : x.toString(36)).join('');
  if (B36.includes(q.type)) return a.map(x => x.toString(36)).join('');
  return a.join('');
}

function decodeAnswer(q, s) {
  s = s || '';
  if (q.type === 'number') return s === '' ? null : s;
  if (s === '') return null;
  if (q.type === 'sim') return s.match(/[audc]\d|A/g) || null;
  const parts = s.split('');
  if (q.type === 'slots' || q.type === 'sort' || q.type === 'table') return parts.map(c => c === 'x' ? null : parseInt(c, 36));
  if (B36.includes(q.type)) return parts.map(c => parseInt(c, 36));
  return parts.map(Number);
}

/* Подсветка кода в карточках: C#, SQL, YAML. Строка разбирается на токены, каждый экранируется отдельно. */
const HL_KW = {
  'C#': new Set('using await var const new while if else return int string decimal bool for foreach in true false null try catch when static async record long object'.split(' ')),
  SQL: new Set('SELECT FROM WHERE AND OR ORDER BY INSERT INTO VALUES UPDATE SET DELETE CREATE TABLE NOT NULL PRIMARY KEY REFERENCES CHECK JOIN LEFT ON AS GROUP ILIKE LIKE IS DESC ASC integer text numeric date'.split(' ')),
};
function hlLine(line, lang) {
  const e = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  if (lang === 'YAML') {
    const m = line.match(/^(\s*-?\s*)([\w.]+)(:)(.*)$/);
    if (m) return `${e(m[1])}<span class="hk">${e(m[2])}</span>${m[3]}<span class="hs">${e(m[4])}</span>`;
    const d = line.match(/^(\s*-\s*)(.*)$/);
    return d ? `${e(d[1])}<span class="hs">${e(d[2])}</span>` : e(line);
  }
  const kw = HL_KW[lang];
  if (!kw) return e(line);
  const re = lang === 'SQL'
    ? /(--.*$)|('(?:[^']|'')*'?)|([A-Za-z_]\w*)|(\d+(?:\.\d+)?)|(\s+)|(.)/g
    : /(\/\/.*$)|(\$?"(?:[^"\\]|\\.)*"?)|([A-Za-z_]\w*)|(\d+(?:\.\d+)?m?)|(\s+)|(.)/g;
  let out = '', m;
  while ((m = re.exec(line))) {
    const [t, com, str, word, num] = m;
    if (com) out += `<span class="hc">${e(com)}</span>`;
    else if (str) out += `<span class="hs">${e(t)}</span>`;
    else if (word) {
      const k = lang === 'SQL' ? kw.has(word.toUpperCase()) || kw.has(word) : kw.has(word);
      if (k) out += `<span class="hk">${word}</span>`;
      else if (lang === 'C#' && /^(Npgsql\w*|Postgres\w*|Console|DateOnly|Dictionary|DBNull|Task|List|OrderView|OrderRow|Order)$/.test(word)) out += `<span class="ht">${word}</span>`;
      else if (lang === 'C#' && /^[A-Z]/.test(word) && line[re.lastIndex] === '(') out += `<span class="hm">${word}</span>`;
      else out += word;
    } else if (num) out += `<span class="hn">${num}</span>`;
    else out += e(t);
  }
  return out;
}

/* Предпросмотр запроса для сборки ввода: ввод подставляется в шаблон, затем запрос разбирается так же, как сервер:
   строка в апострофах (два апострофа подряд — апостроф внутри строки), имя в кавычках, комментарий от -- до конца.
   Символы ввода подчёркнуты; ввод вне строки и комментария выделен как код. */
function sqlPreview(template, text) {
  const at = template.indexOf('{}');
  const sql = template.slice(0, at) + text + template.slice(at + 2);
  const from = at, to = at + text.length;
  const kinds = [];
  let st = 'code';
  for (let i = 0; i < sql.length; i++) {
    const c = sql[i];
    if (st === 'code') {
      if (c === '-' && sql[i + 1] === '-') { st = 'cmt'; kinds.push('cmt'); continue; }
      if (c === "'") { st = 'str'; kinds.push('str'); continue; }
      if (c === '"') { st = 'id'; kinds.push('code'); continue; }
      kinds.push('code');
    } else if (st === 'str') {
      kinds.push('str');
      if (c === "'") { if (sql[i + 1] === "'") { kinds.push('str'); i++; } else st = 'code'; }
    } else if (st === 'id') {
      kinds.push('code');
      if (c === '"') st = 'code';
    } else kinds.push('cmt');
  }
  const e = t => t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  let out = '', run = '', cls = null;
  for (let i = 0; i < sql.length; i++) {
    const mine = i >= from && i < to;
    const k = kinds[i] + (mine ? (kinds[i] === 'code' && sql[i] !== ' ' ? ' u inj' : ' u') : '');
    if (k !== cls) { if (run) out += `<span class="sq ${cls}">${e(run)}</span>`; run = ''; cls = k; }
    run += sql[i];
  }
  if (run) out += `<span class="sq ${cls}">${e(run)}</span>`;
  return { html: out, broken: st === 'str' || st === 'id' };
}

function gradeFor(score) {
  return QUIZ.grades.find(g => score >= g.min) || QUIZ.grades[QUIZ.grades.length - 1];
}
